/**
 * The MySMS API clients, generated by OpenAPI Generator (`typescript-fetch`) from each module's springdoc
 * document (`backend/<module>/target/openapi/api-docs.yml`): one namespace per module, e.g. `master.CountryApi`, `master.Country`. All modules share one runtime
 * (`Configuration`, `ResponseError`, `FetchError`...).
 *
 * Applications never import this package directly — `@mysms/core` wraps it with auth, retries,
 * problem+json parsing, ETags and idempotency keys (ui/05 §1, §4, §6).
 */
export * from './generated';
